class Solution {
    public List<String> wordBreak(String s, List<String> wordDict) {
        java.util.Set<String> dict = new java.util.HashSet<>(wordDict);
        java.util.Map<Integer, List<String>> memo = new java.util.HashMap<>();
        return dfs(s, 0, dict, memo);
    }
    private List<String> dfs(String s, int start, java.util.Set<String> dict, java.util.Map<Integer, List<String>> memo) {
        if (memo.containsKey(start)) return memo.get(start);
        List<String> result = new java.util.ArrayList<>();
        if (start == s.length()) { result.add(""); return result; }
        for (int end = start + 1; end <= s.length(); end++) {
            String word = s.substring(start, end);
            if (dict.contains(word)) {
                List<String> rest = dfs(s, end, dict, memo);
                for (String r : rest) {
                    result.add(word + (r.isEmpty() ? "" : " " + r));
                }
            }
        }
        memo.put(start, result);
        return result;
    }
}
